namespace prettify_tests {
  using namespace simdjson;
  using namespace simdjson::dom;

  bool check_prettify(const std::string & input, const std::string & expected) {
    dom::parser parser;
    dom::element elem;
    padded_string padded(input);
    ASSERT_SUCCESS( parser.parse(padded).get(elem) );
    std::string actual = simdjson::prettify(elem);
    if (actual != expected) {
      std::cerr << "prettify produced:" << std::endl << actual << std::endl
                << "but we expected:" << std::endl << expected << std::endl;
      return false;
    }
    // also check the simdjson_result overload
    ASSERT_SUCCESS( parser.parse(padded).get(elem) );
#if SIMDJSON_EXCEPTIONS
    if (simdjson::prettify(parser.parse(padded)) != expected) {
      std::cerr << "prettify(simdjson_result) failed" << std::endl;
      return false;
    }
#endif
    return true;
  }

  bool test_prettify_scalar() {
    std::cout << "Running " << __func__ << std::endl;
    return check_prettify("1", "1") &&
           check_prettify("\"a string\"", "\"a string\"") &&
           check_prettify("true", "true") &&
           check_prettify("null", "null");
  }
  bool test_prettify_array() {
    std::cout << "Running " << __func__ << std::endl;
    const std::string expected(R"([
    1,
    2,
    3
])");
    return check_prettify("[ 1, 2, 3 ]", expected);
  }
  bool test_prettify_object() {
    std::cout << "Running " << __func__ << std::endl;
    const std::string expected(R"({
    "foo": 1,
    "bar": [
        1,
        2
    ]
})");
    return check_prettify(R"({ "foo": 1, "bar": [ 1, 2 ] })", expected);
  }
  bool test_prettify_nested() {
    std::cout << "Running " << __func__ << std::endl;
    const std::string expected(R"({
    "foo": [
        1,
        {
            "a": 1
        }
    ],
    "bar": {}
})");
    return check_prettify(R"({"foo":[1,{"a":1}], "bar":{}})", expected);
  }
  bool test_prettify_empty_containers() {
    std::cout << "Running " << __func__ << std::endl;
    return check_prettify("[]", "[]") &&
           check_prettify("{}", "{}") &&
           check_prettify(R"({ "a": [] })", R"({"a": []})") &&
           check_prettify(R"([1, []])", R"([
    1,
    []
])");
  }
  bool run() {
    return test_prettify_scalar() &&
           test_prettify_array() &&
           test_prettify_object() &&
           test_prettify_nested() &&
           test_prettify_empty_containers();
  }
}

